{
  "name": "热循环仪",
  "name_en": "Thermocycler",
  "manufacturer": "",
  "description": "用于 PCR 等热循环实验的通用热循环仪，支持加热块与热盖温度控制、开合盖、运行多阶段温控程序，并查询当前温度、循环进度与运行状态。",
  "description_en": "A generic thermocycler for PCR and other thermal cycling workflows. It supports block and heated-lid temperature control, lid open/close operations, execution of multi-stage temperature protocols, and queries of current temperature, cycle progress, and run status.",
  "actions": [
    {
      "action_name": "auto-open_lid",
      "description": "打开热循环仪上盖。",
      "description_en": "Open the thermocycler lid."
    },
    {
      "action_name": "auto-close_lid",
      "description": "关闭热循环仪上盖。",
      "description_en": "Close the thermocycler lid."
    },
    {
      "action_name": "auto-set_block_temperature",
      "description": "设置加热块目标温度。",
      "description_en": "Set the target temperature of the block."
    },
    {
      "action_name": "auto-set_lid_temperature",
      "description": "设置热盖目标温度。",
      "description_en": "Set the target temperature of the heated lid."
    },
    {
      "action_name": "auto-deactivate_block",
      "description": "关闭加热块加热。",
      "description_en": "Deactivate block heating."
    },
    {
      "action_name": "auto-deactivate_lid",
      "description": "关闭热盖加热。",
      "description_en": "Deactivate lid heating."
    },
    {
      "action_name": "auto-run_protocol",
      "description": "运行多阶段温控程序。",
      "description_en": "Run a multi-stage temperature protocol."
    },
    {
      "action_name": "auto-run_pcr_profile",
      "description": "运行 PCR 热循环程序。",
      "description_en": "Run a PCR thermal cycling profile."
    },
    {
      "action_name": "auto-get_block_current_temperature",
      "description": "获取加热块当前温度。",
      "description_en": "Get the current block temperature."
    },
    {
      "action_name": "auto-get_block_target_temperature",
      "description": "获取加热块目标温度。",
      "description_en": "Get the target block temperature."
    },
    {
      "action_name": "auto-get_lid_current_temperature",
      "description": "获取热盖当前温度。",
      "description_en": "Get the current lid temperature."
    },
    {
      "action_name": "auto-get_lid_target_temperature",
      "description": "获取热盖目标温度。",
      "description_en": "Get the target lid temperature."
    },
    {
      "action_name": "auto-get_lid_open",
      "description": "获取上盖是否打开。",
      "description_en": "Get whether the lid is open."
    },
    {
      "action_name": "auto-get_lid_status",
      "description": "获取热盖状态。",
      "description_en": "Get the lid status."
    },
    {
      "action_name": "auto-get_block_status",
      "description": "获取加热块状态。",
      "description_en": "Get the block status."
    },
    {
      "action_name": "auto-get_hold_time",
      "description": "获取当前步骤剩余保持时间。",
      "description_en": "Get the remaining hold time for the current step."
    },
    {
      "action_name": "auto-get_current_cycle_index",
      "description": "获取当前循环编号。",
      "description_en": "Get the current cycle index."
    },
    {
      "action_name": "auto-get_total_cycle_count",
      "description": "获取总循环次数。",
      "description_en": "Get the total cycle count."
    },
    {
      "action_name": "auto-get_current_step_index",
      "description": "获取当前步骤编号。",
      "description_en": "Get the current step index."
    },
    {
      "action_name": "auto-get_total_step_count",
      "description": "获取当前循环中的总步骤数。",
      "description_en": "Get the total number of steps in the current cycle."
    },
    {
      "action_name": "auto-wait_for_block",
      "description": "等待加热块达到目标温度。",
      "description_en": "Wait for the block to reach its target temperature."
    },
    {
      "action_name": "auto-wait_for_lid",
      "description": "等待热盖达到目标温度。",
      "description_en": "Wait for the lid to reach its target temperature."
    },
    {
      "action_name": "auto-is_profile_running",
      "description": "获取温控程序是否仍在运行。",
      "description_en": "Get whether a temperature profile is still running."
    },
    {
      "action_name": "auto-wait_for_profile_completion",
      "description": "等待温控程序运行完成。",
      "description_en": "Wait for the temperature profile to complete."
    },
    {
      "action_name": "auto-serialize",
      "description": "导出设备的 JSON 可序列化表示。",
      "description_en": "Serialize the device to a JSON-compatible representation."
    }
  ],
  "tag_hints": [
    "PCR thermocycling",
    "heated lid",
    "block temperature control",
    "thermal cycling profiles",
    "multi-stage protocol execution",
    "cycle progress monitoring"
  ]
}

